@SpringBootTest(webEnvironment=SpringBootTest.WebEnvironment.RANDOM_PORT,properties={"dreamcore.exports.worker-enabled=false","dreamcore.tasks.agent-mode=off","dreamcore.tasks.enabled=false"})
class ExportBatchIntegrationTest {
 @Autowired com.dreamcore.workspace.retention.RetentionService retention;@Autowired JdbcTemplate db;@Autowired ExportBatchService service;@Autowired ExportBatchWorker worker;@Autowired ExportSources sources;@Autowired DocumentService documents;@Autowired DocumentPublicationService publications;@Autowired MaterialService materials;@Autowired PasswordEncoder passwords;@LocalServerPort int port;
 UUID tenant,owner,reader,admin,personal,source,destination,doc,task,conversation;final String password="synthetic-export-password";final JsonMapper json=new JsonMapper();
 String email(UUID a){return "export-"+a+"@example.test";}
 @BeforeEach void fixture(){tenant=UUID.randomUUID();owner=UUID.randomUUID();reader=UUID.randomUUID();admin=UUID.randomUUID();personal=UUID.randomUUID();source=UUID.randomUUID();destination=UUID.randomUUID();doc=UUID.randomUUID();task=UUID.randomUUID();conversation=UUID.randomUUID();db.update("INSERT INTO tenants(id,name) VALUES (?,'合成批量导出')",tenant);
  for(UUID a:List.of(owner,reader,admin)){db.update("INSERT INTO accounts(id,email,display_name,password_hash) VALUES (?,?,?,?)",a,email(a),"合成导出员工",passwords.encode(password));db.update("INSERT INTO tenant_memberships(tenant_id,account_id,role) VALUES (?,?,?)",tenant,a,a.equals(admin)?"TENANT_ADMIN":"MEMBER");}
  db.update("INSERT INTO workspaces(id,tenant_id,owner_id,name,kind) VALUES (?,?,?,'我的空间','PERSONAL'),(?,?,?,'原资料','SHARED'),(?,?,?,'独立成果','SHARED')",personal,tenant,owner,source,tenant,owner,destination,tenant,owner);
  db.update("INSERT INTO workspace_members(tenant_id,workspace_id,account_id,can_maintain) VALUES (?,?,?,true),(?,?,?,true),(?,?,?,false)",tenant,source,owner,tenant,destination,owner,tenant,destination,reader);
  db.update("INSERT INTO conversations(id,tenant_id,workspace_id,owner_id,title) VALUES (?,?,?,?,'原会话不应进入共享包')",conversation,tenant,source,owner);
  db.update("INSERT INTO conversation_tasks(id,tenant_id,workspace_id,conversation_id,requested_by,prompt,mode,status,revision,attempt,reply,execution_class,finished_at) VALUES (?,?,?,?,?,'私人原提示','AGENT','SUCCEEDED',3,1,'合成产出','verification',now())",task,tenant,source,conversation,owner);
  db.update("INSERT INTO private_documents(id,tenant_id,owner_id,workspace_id,source_workspace_id,source_conversation_id,source_task_id,revision) VALUES (?,?,?,?,?,?,?,1)",doc,tenant,owner,personal,source,conversation,task);
  db.update("INSERT INTO private_document_versions(tenant_id,document_id,number,title,body) VALUES (?,?,1,'已选旧标题','固定版本一正文；这是合成数据。')",tenant,doc);
 }
 @AfterEach void cleanupFixture(){db.update("DELETE FROM export_archive_chunks WHERE batch_id IN(SELECT id FROM export_batches WHERE tenant_id=?)",tenant);db.update("UPDATE export_batches SET state='REMOVED',cleanup_state='COMPLETE',lease_token=NULL,lease_until=NULL WHERE tenant_id=?",tenant);}
 void grant(UUID a,UUID workspace){db.update("INSERT INTO governance_capabilities(tenant_id,account_id,workspace_id,capability,granted_by) VALUES (?,?,?,'BULK_EXPORT',?) ON CONFLICT DO NOTHING",tenant,a,workspace,owner);}
 ExportSources.Selection selection(){return new ExportSources.Selection(doc,1,"docx");}
 ExportBatchService.Batch create(List<ExportSources.Selection> selected){grant(owner,null);return service.create(owner,tenant,personal,"PRIVATE",UUID.randomUUID(),1,selected);}
 ExportBatchService.Batch ready(){var b=create(List.of(selection()));var j=service.claim();assertNotNull(j);assertEquals(b.id(),j.id());worker.build(j);return service.get(owner,tenant,b.id());}
 byte[] download(UUID actor,UUID id)throws IOException{var out=new ByteArrayOutputStream();service.download(actor,tenant,id,info->assertTrue(info.bytes()>0),out);return out.toByteArray();}
 Map<String,byte[]> unzip(byte[] bytes)throws IOException{var files=new LinkedHashMap<String,byte[]>();try(var zip=new ZipInputStream(new ByteArrayInputStream(bytes))){ZipEntry e;while((e=zip.getNextEntry())!=null){assertFalse(e.getName().startsWith("/"));assertFalse(e.getName().contains(".."));files.put(e.getName(),zip.readAllBytes());}}return files;}
 UUID[] uncitedSource(){var f=materials.upload(owner,tenant,source,null,null,null,UUID.randomUUID(),new MockMultipartFile("file","input.txt","text/plain","合成原资料".getBytes()));UUID version=materials.detail(owner,tenant,source,f.id(),0,20).versions().getFirst().id(),run=UUID.randomUUID(),chunk=UUID.randomUUID(),token=UUID.randomUUID();db.update("INSERT INTO knowledge_runs(id,tenant_id,workspace_id,material_id,version_id,generation,requested_by,status) VALUES (?,?,?,?,?,1,?,'READY')",run,tenant,source,f.id(),version,owner);db.update("INSERT INTO knowledge_chunks(id,tenant_id,workspace_id,material_id,version_id,run_id,ordinal,locator,method,content) VALUES (?,?,?,?,?,?,0,'p1','TEXT','未引用但实际读过')",chunk,tenant,source,f.id(),version,run);db.update("INSERT INTO conversation_agent_grants(tenant_id,workspace_id,task_id,attempt_id,chunk_id) VALUES (?,?,?,?,?)",tenant,source,task,token,chunk);return new UUID[]{f.id(),version};}
 @Test void bulkCapabilityIsExplicitAndAdminCannotReadPrivateContent(){assertFalse(service.options(owner,tenant,personal,"PRIVATE",null,"docx",0,20).canExport());assertEquals(403,assertThrows(IdentityException.class,()->service.create(owner,tenant,personal,"PRIVATE",UUID.randomUUID(),1,List.of(selection()))).status);grant(admin,null);assertThrows(IdentityException.class,()->service.options(admin,tenant,personal,"PRIVATE",null,"docx",0,20));var b=ready();assertEquals(404,assertThrows(IdentityException.class,()->service.get(admin,tenant,b.id())).status);}
 @Test void realArchiveContainsExactSelectedVersionAndManifestNotLatestEdit()throws Exception{var b=ready();assertEquals("READY",b.state());assertTrue(b.canDownload());documents.save(owner,tenant,doc,UUID.randomUUID(),1,"新标题","后来版本二的正文");var files=unzip(download(owner,b.id()));assertEquals(2,files.size());var docx=unzip(files.entrySet().stream().filter(e->e.getKey().endsWith(".docx")).findFirst().orElseThrow().getValue());String xml=new String(docx.get("word/document.xml"),java.nio.charset.StandardCharsets.UTF_8);assertTrue(xml.contains("固定版本一正文"));assertFalse(xml.contains("后来版本二"));var manifest=json.readTree(files.get("_export-manifest.json"));assertTrue(manifest.get("complete").asBoolean());assertEquals(1,manifest.get("items").get(0).get("selection").get("version").asInt());assertTrue(db.queryForObject("SELECT max(octet_length(content)) FROM export_archive_chunks WHERE batch_id=?",Integer.class,b.id())<=65536);}
 @Test void missingItemsAreHonestPartialAndZeroSuccessCannotDownload()throws Exception{var b=create(List.of(selection(),new ExportSources.Selection(UUID.randomUUID(),1,"pdf")));worker.build(service.claim());var result=service.get(owner,tenant,b.id());assertEquals("PARTIAL",result.state());assertEquals(1,result.includedCount());assertEquals(1,result.failedCount());assertTrue(result.canDownload());var manifest=json.readTree(unzip(download(owner,b.id())).get("_export-manifest.json"));assertFalse(manifest.get("complete").asBoolean());assertEquals("EXPORT_ITEM_UNAVAILABLE",manifest.get("items").get(1).get("errorCode").asString());var empty=create(List.of(new ExportSources.Selection(UUID.randomUUID(),1,"docx")));worker.build(service.claim());assertEquals("FAILED",service.get(owner,tenant,empty.id()).state());assertEquals(0,db.queryForObject("SELECT count(*) FROM export_archive_chunks WHERE batch_id=?",Integer.class,empty.id()));assertEquals(410,assertThrows(IdentityException.class,()->download(owner,empty.id())).status);}
 @Test void sourceRevocationBlocksExistingPackageAndRedactsCachedNames()throws Exception{var b=ready();db.update("DELETE FROM workspace_members WHERE tenant_id=? AND workspace_id=? AND account_id=?",tenant,source,owner);var detail=service.get(owner,tenant,b.id());assertFalse(detail.canDownload());assertNull(detail.items().getFirst().title());assertNull(detail.items().getFirst().archivePath());assertTrue(service.options(owner,tenant,personal,"PRIVATE",null,"docx",0,20).items().isEmpty());var bytes=new ByteArrayOutputStream();assertThrows(IdentityException.class,()->service.download(owner,tenant,b.id(),x->fail("Must not emit download headers"),bytes));assertEquals(0,bytes.size());}
 @Test void independentEnterprisePackageSurvivesPrivateSourceLossButNotTargetRevocation()throws Exception{var p=publications.publish(owner,tenant,doc,1,UUID.randomUUID(),destination,null,null,null,"docx",true);grant(reader,destination);var options=service.options(reader,tenant,destination,"ENTERPRISE",null,"docx",0,20);assertEquals(1,options.items().size());assertFalse(json.writeValueAsString(options).contains(doc.toString()));var b=service.create(reader,tenant,destination,"ENTERPRISE",UUID.randomUUID(),1,List.of(options.items().getFirst().selection()));worker.build(service.claim());db.update("DELETE FROM workspace_members WHERE tenant_id=? AND workspace_id=? AND account_id=?",tenant,source,owner);assertEquals("READY",service.get(reader,tenant,b.id()).state());assertTrue(download(reader,b.id()).length>0);db.update("DELETE FROM workspace_members WHERE tenant_id=? AND workspace_id=? AND account_id=?",tenant,destination,reader);assertThrows(IdentityException.class,()->download(reader,b.id()));assertNull(service.get(reader,tenant,b.id()).items().getFirst().title());}
 @Test void capabilityRevocationDoesNotLeaveOldArchiveDownloadable()throws Exception{var b=ready();db.update("DELETE FROM governance_capabilities WHERE tenant_id=? AND account_id=? AND capability='BULK_EXPORT'",tenant,owner);assertEquals(403,assertThrows(IdentityException.class,()->download(owner,b.id())).status);assertFalse(service.get(owner,tenant,b.id()).canDownload());}
 @Test void sourcePurgeDeletesOnlineArchiveAndMarksIndependentCleanupReceipt()throws Exception{UUID[] s=uncitedSource();var b=ready();assertEquals(1,db.queryForObject("SELECT count(*) FROM export_item_sources WHERE batch_id=?",Integer.class,b.id()));db.queryForList("SELECT scrub_export_material(?)",s[0]);var result=service.get(owner,tenant,b.id());assertEquals("REVOKED",result.state());assertEquals("COMPLETE",result.cleanup().state());assertEquals("BACKUPS_SEPARATE",result.cleanup().backupState());assertTrue(result.cleanup().removedBytes()>0);assertEquals(0,db.queryForObject("SELECT count(*) FROM export_archive_chunks WHERE batch_id=?",Integer.class,b.id()));assertEquals(410,assertThrows(IdentityException.class,()->download(owner,b.id())).status);assertEquals("固定版本一正文；这是合成数据。",documents.detail(owner,tenant,doc,1).version().body());}
 @Test void deadlineBlocksImmediatelyAndCleanupActuallyRemovesChunksWithoutDeletingDocument()throws Exception{var b=ready();var created=b.createdAt();db.update("UPDATE export_batches SET expires_at=now()-interval '1 second' WHERE id=?",b.id());assertFalse(service.get(owner,tenant,b.id()).canDownload());assertEquals(410,assertThrows(IdentityException.class,()->download(owner,b.id())).status);worker.runOnce();var gone=service.get(owner,tenant,b.id());assertEquals("EXPIRED",gone.state());assertEquals("COMPLETE",gone.cleanup().state());assertNotNull(gone.cleanup().completedAt());assertTrue(gone.cleanup().removedBytes()>0);assertEquals(created,gone.createdAt());assertEquals(0,db.queryForObject("SELECT count(*) FROM export_archive_chunks WHERE batch_id=?",Integer.class,b.id()));assertEquals(1,documents.detail(owner,tenant,doc,1).version().number());assertThrows(IdentityException.class,()->service.command(owner,tenant,b.id(),UUID.randomUUID(),gone.revision(),"RETRY"));}
 @Test void cleanupFailureHasRealFailureStateThenRetryRemovesRemainingBytes(){var b=ready();service.command(owner,tenant,b.id(),UUID.randomUUID(),b.revision(),"REMOVE");db.execute("CREATE FUNCTION fail_export_test_delete() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'synthetic cleanup failure'; END $$");db.execute("CREATE TRIGGER export_test_delete BEFORE DELETE ON export_archive_chunks FOR EACH ROW EXECUTE FUNCTION fail_export_test_delete()");try{worker.runOnce();assertEquals("FAILED",service.get(owner,tenant,b.id()).cleanup().state());assertTrue(db.queryForObject("SELECT count(*) FROM export_archive_chunks WHERE batch_id=?",Integer.class,b.id())>0);}finally{db.execute("DROP TRIGGER export_test_delete ON export_archive_chunks");db.execute("DROP FUNCTION fail_export_test_delete()");}worker.runOnce();assertEquals("COMPLETE",service.get(owner,tenant,b.id()).cleanup().state());assertEquals(0,db.queryForObject("SELECT count(*) FROM export_archive_chunks WHERE batch_id=?",Integer.class,b.id()));}
 @Test void staleWorkerCannotPublishOrAppendToNewGeneration(){var b=create(List.of(selection()));var old=service.claim();db.update("UPDATE export_batches SET lease_until=now()-interval '1 second' WHERE id=?",b.id());var next=service.claim();assertNotEquals(old.token(),next.token());assertThrows(IdentityException.class,()->service.chunk(old,0,new byte[]{1}));worker.build(old);assertEquals("GENERATING",service.get(owner,tenant,b.id()).state());worker.build(next);assertEquals("READY",service.get(owner,tenant,b.id()).state());}
 @Test void duplicateCreateReplaysSameBatchAndCannotChangeSelectionOrDeadline()throws Exception{grant(owner,null);UUID key=UUID.randomUUID();try(var pool=Executors.newFixedThreadPool(2)){var calls=pool.invokeAll(List.<Callable<ExportBatchService.Batch>>of(()->service.create(owner,tenant,personal,"PRIVATE",key,1,List.of(selection())),()->service.create(owner,tenant,personal,"PRIVATE",key,1,List.of(selection()))));assertEquals(calls.get(0).get().id(),calls.get(1).get().id());}assertEquals(1,db.queryForObject("SELECT count(*) FROM export_batches WHERE tenant_id=?",Integer.class,tenant));assertEquals("IDEMPOTENCY_CONFLICT",assertThrows(IdentityException.class,()->service.create(owner,tenant,personal,"PRIVATE",key,3,List.of(selection()))).code);}
 @Test void lifecycleScopeCleanupFencesInFlightGenerationAndLeavesBusinessDocument(){var b=create(List.of(selection()));var job=service.claim();var file=sources.export(owner,tenant,personal,"PRIVATE",selection());service.reserve(job,1,file,"001.docx");service.chunk(job,0,new byte[]{1,2,3});db.queryForList("SELECT scrub_export_scope(?,?)",tenant,owner);assertEquals("REVOKED",service.get(owner,tenant,b.id()).state());assertEquals("COMPLETE",service.get(owner,tenant,b.id()).cleanup().state());assertThrows(IdentityException.class,()->service.chunk(job,1,new byte[]{4}));assertEquals(0,db.queryForObject("SELECT count(*) FROM export_archive_chunks WHERE batch_id=?",Integer.class,b.id()));assertEquals(1,documents.detail(owner,tenant,doc,1).version().number());}
 @Test void overlargeAndDuplicateSelectionCannotBecomeUnboundedWork(){grant(owner,null);assertThrows(IdentityException.class,()->service.create(owner,tenant,personal,"PRIVATE",UUID.randomUUID(),1,Collections.nCopies(51,selection())));assertThrows(IdentityException.class,()->service.create(owner,tenant,personal,"PRIVATE",UUID.randomUUID(),1,List.of(selection(),selection())));assertThrows(IdentityException.class,()->service.create(owner,tenant,personal,"PRIVATE",UUID.randomUUID(),30,List.of(selection())));assertEquals(0,db.queryForObject("SELECT count(*) FROM export_batches WHERE tenant_id=?",Integer.class,tenant));}
 final class Client{final HttpClient http=HttpClient.newBuilder().cookieHandler(new CookieManager(null,CookiePolicy.ACCEPT_ALL)).build();HttpResponse<byte[]> send(String method,String path,Object body,boolean csrf)throws Exception{var r=HttpRequest.newBuilder(URI.create("http://127.0.0.1:"+port+path)).header("Content-Type","application/json");if(csrf){var c=json.readTree(send("GET","/api/v1/auth/csrf",null,false).body());r.header(c.get("headerName").asString(),c.get("token").asString());}return http.send(r.method(method,body==null?HttpRequest.BodyPublishers.noBody():HttpRequest.BodyPublishers.ofString(json.writeValueAsString(body))).build(),HttpResponse.BodyHandlers.ofByteArray());}}
 @Test void actualHttpZipAndConflictErrorsKeepContractAndNoStore()throws Exception{var b=ready();var c=new Client();assertEquals(200,c.send("POST","/api/v1/auth/login",Map.of("email",email(owner),"password",password),true).statusCode());String root="/api/v1/tenants/"+tenant+"/export-batches/"+b.id();var r=c.send("GET",root+"/archive",null,false);assertEquals(200,r.statusCode());assertEquals("application/zip",r.headers().firstValue("content-type").orElse(""));assertEquals(ObjectStore.sha256(r.body()),r.headers().firstValue("x-content-sha256").orElse(""));assertTrue(r.headers().firstValue("cache-control").orElse("").contains("no-store"));assertEquals(2,unzip(r.body()).size());var conflict=c.send("POST",root,Map.of("requestId",UUID.randomUUID(),"expectedRevision",1,"action","REMOVE"),true);assertEquals(409,conflict.statusCode());assertEquals("1.0",json.readTree(conflict.body()).get("contractVersion").asString());db.update("UPDATE export_batches SET expires_at=now()-interval '1 second' WHERE id=?",b.id());var expired=c.send("GET",root+"/archive",null,false);assertEquals(410,expired.statusCode());assertEquals("EXPORT_NOT_DOWNLOADABLE",json.readTree(expired.body()).get("code").asString());}
 @Test void policyLimitsNewPackagesAndFailedGenerationKeepsOriginalDeadline(){
  grant(owner,null);UUID key=UUID.randomUUID();var original=service.create(owner,tenant,personal,"PRIVATE",key,7,List.of(selection()));
  var job=service.claim();var stamp=service.stamp(job);assertEquals(java.time.Duration.ofDays(7),java.time.Duration.between(stamp.generatedAt(),stamp.expiresAt()));
  retention.configure(admin,tenant,"EXPORT_PACKAGE",UUID.randomUUID(),0,1,"后续新包最多一天");
  assertEquals(List.of(1),service.options(owner,tenant,personal,"PRIVATE",null,"docx",0,20).retentionDays());
  assertEquals(409,assertThrows(IdentityException.class,()->service.create(owner,tenant,personal,"PRIVATE",UUID.randomUUID(),3,List.of(selection()))).status);
  assertEquals(original.id(),service.create(owner,tenant,personal,"PRIVATE",key,7,List.of(selection())).id());
  service.fail(job,"SYNTHETIC_GENERATION_INTERRUPTED");var failed=service.get(owner,tenant,original.id());service.command(owner,tenant,original.id(),UUID.randomUUID(),failed.revision(),"RETRY");
  var retry=service.claim();assertEquals(stamp,service.stamp(retry));worker.build(retry);var done=service.get(owner,tenant,original.id());
  assertEquals("READY",done.state());assertEquals(stamp.expiresAt(),done.expiresAt());
  assertEquals(0,db.queryForObject("SELECT retention_policy_revision FROM export_batches WHERE id=?",Integer.class,original.id()));
  var next=service.create(owner,tenant,personal,"PRIVATE",UUID.randomUUID(),1,List.of(selection()));
  assertEquals(1,db.queryForObject("SELECT retention_policy_revision FROM export_batches WHERE id=?",Integer.class,next.id()));
 }

}
